CREATE TRIGGER baseline_line_no_delete BEFORE DELETE ON baseline_lines BEGIN SELECT RAISE(ABORT,'成交明细不可删除'); END;
CREATE TRIGGER locked_quote_context BEFORE UPDATE ON quotation_history WHEN OLD.ordered_at IS NOT NULL AND (NEW.document_type IS NOT OLD.document_type OR NEW.parent_order_id IS NOT OLD.parent_order_id OR NEW.project_name IS NOT OLD.project_name) BEGIN SELECT RAISE(ABORT,'已下单报价身份不可修改'); END;
CREATE TRIGGER stock_available_guard BEFORE INSERT ON stock_movements WHEN COALESCE((SELECT SUM(quantity) FROM stock_movements WHERE product_id=NEW.product_id),0)+NEW.quantity < COALESCE((SELECT SUM(quantity) FROM stock_reservations WHERE product_id=NEW.product_id AND status='active'),0)-0.000001 BEGIN SELECT RAISE(ABORT,'库存已被占用，不能撤销或扣减该数量'); END;
CREATE TABLE purchase_item_changes(id TEXT PRIMARY KEY,change_id TEXT NOT NULL REFERENCES order_changes(id),item_id TEXT NOT NULL REFERENCES order_items(id),old_product TEXT,old_model TEXT,old_quantity REAL,old_price REAL,new_product TEXT NOT NULL REFERENCES products(id),new_model TEXT NOT NULL,new_quantity REAL NOT NULL,new_price REAL NOT NULL,new_name TEXT NOT NULL,new_unit TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES employees(id),applied INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TRIGGER purchase_change_guard BEFORE INSERT ON purchase_item_changes WHEN NOT EXISTS(SELECT 1 FROM order_changes c JOIN order_items i ON i.baseline_line_id=c.baseline_line_id JOIN employees e ON e.id=NEW.actor_id WHERE c.id=NEW.change_id AND c.status='confirmed' AND i.id=NEW.item_id AND e.role='purchasing' AND e.status='active' AND i.product_id=NEW.old_product AND i.model=NEW.old_model AND i.quantity=NEW.old_quantity AND i.unit_price=NEW.old_price AND c.new_product_id=NEW.new_product AND c.new_model=NEW.new_model AND NEW.new_quantity>0 AND NEW.new_price>=0 AND i.shipped_quantity=0 AND i.received_quantity=0 AND i.stocked_quantity=0 AND i.production_completed=0) BEGIN SELECT RAISE(ABORT,'采购变更与销售确认或当前执行状态不一致'); END;
DROP TRIGGER item_commercial_fields_fixed;
CREATE TRIGGER item_commercial_fields_fixed BEFORE UPDATE OF id,order_id,quantity,unit_price,amount,product_id,model ON order_items WHEN (NEW.id IS NOT OLD.id OR NEW.order_id IS NOT OLD.order_id OR NEW.quantity IS NOT OLD.quantity OR NEW.unit_price IS NOT OLD.unit_price OR NEW.amount IS NOT OLD.amount OR NEW.product_id IS NOT OLD.product_id OR (OLD.baseline_line_id IS NOT NULL AND NEW.model IS NOT OLD.model)) AND NOT EXISTS(SELECT 1 FROM purchase_item_changes c WHERE c.item_id=OLD.id AND c.applied=0 AND c.old_quantity=OLD.quantity AND c.old_price=OLD.unit_price AND c.old_product=OLD.product_id AND c.new_quantity=NEW.quantity AND c.new_price=NEW.unit_price AND c.new_product=NEW.product_id AND c.new_model=NEW.model AND NEW.id=OLD.id AND NEW.order_id=OLD.order_id AND abs(NEW.amount-NEW.quantity*NEW.unit_price)<0.00001) BEGIN SELECT RAISE(ABORT,'采购数量与型号须从销售确认的变更单执行'); END;
CREATE TRIGGER purchase_change_apply AFTER INSERT ON purchase_item_changes BEGIN
 UPDATE order_items SET product_id=NEW.new_product,product_name=NEW.new_name,model=NEW.new_model,quantity=NEW.new_quantity,unit_price=NEW.new_price,amount=NEW.new_quantity*NEW.new_price,unit=NEW.new_unit WHERE id=NEW.item_id;
 UPDATE purchase_item_changes SET applied=1 WHERE id=NEW.id;
END;
CREATE TRIGGER purchase_change_no_delete BEFORE DELETE ON purchase_item_changes BEGIN SELECT RAISE(ABORT,'采购变更记录不可删除'); END;
CREATE TRIGGER purchase_change_immutable BEFORE UPDATE ON purchase_item_changes WHEN OLD.applied=1 OR NEW.applied!=1 OR NEW.id!=OLD.id OR NEW.item_id!=OLD.item_id OR NEW.change_id!=OLD.change_id OR NEW.new_quantity!=OLD.new_quantity OR NEW.new_price!=OLD.new_price OR NEW.new_product!=OLD.new_product OR NEW.new_model!=OLD.new_model BEGIN SELECT RAISE(ABORT,'采购变更记录不可覆盖'); END;
CREATE TRIGGER deposit_no_update BEFORE UPDATE ON deposit_confirmations BEGIN SELECT RAISE(ABORT,'到账确认不可覆盖'); END;
CREATE TRIGGER deposit_no_delete BEFORE DELETE ON deposit_confirmations BEGIN SELECT RAISE(ABORT,'到账确认不可删除'); END;
